  "Välj": "Velg",
  "Välj din avatar eller skapa en ny.": "Velg avataren din eller lag en ny.",
  "Välj en bok. Att läsa ut den tar en timme och ger en utbildningspoäng första gången.": "Velg en bok. Å lese den ut tar en time og gir ett utdanningspoeng første gang.",
  "Välj en fröpåse. Vattna bädden varje dag – två dagar utan vatten och plantorna vissnar. Skörden hamnar i skafferiet.": "Velg en frøpose. Vann bedet hver dag – to dager uten vann, og plantene visner. Avlingen havner i matskapet.",
  "Välj en häst.": "Velg en hest.",
  "Välj en låt – den går hemma tills du stänger av eller lägger dig. Alla låtar i Pixelstaden finns här.": "Velg en sang – den spiller hjemme til du slår av eller legger deg. Alle sangene i Pixelbyen finnes her.",
  "Välj en möbel först": "Velg et møbel først",
  "Välj en ny frisyr eller färg först.": "Velg en ny frisyre eller farge først.",
  "Välj en ny frisyr eller hårfärg – förhandsbilden visar hur det blir på dig.": "Velg en ny frisyre eller hårfarge – forhåndsbildet viser hvordan det blir på deg.",
  "Välj ett belopp.": "Velg et beløp.",
  "Välj ett märke": "Velg et merke",
  "Välj ett ställe på kartan.": "Velg et sted på kartet.",
  "Välj färg – en ballong kostar {0}. Den följer med dig på tivolit hela dagen!": "Velg farge – en ballong koster {0}. Den følger med deg på tivoliet hele dagen!",
  "Välj hur högt du siktar i varje mål. Du har klarat livet i Pixelstaden när alla fyra är nådda samtidigt.": "Velg hvor høyt du sikter i hvert mål. Du har klart livet i Pixelbyen når alle fire er nådd samtidig.",
  "Välj hur mycket du vill sätta in.": "Velg hvor mye du vil sette inn.",
  "Välj hur mycket du vill ta ut.": "Velg hvor mye du vil ta ut.",
  "Välj kana. Trapporna upp är branta – håll i räcket.": "Velg sklie. Trappene opp er bratte – hold i rekkverket.",
  "Välj någon i laget – eller skriv ett eget förnamn och nummer.": "Velg noen på laget – eller skriv et eget fornavn og nummer.",
  "Välj något från menyn först!": "Velg noe fra menyen først!",
  "Välj något i butiken så slår jag in det!": "Velg noe i butikken, så slår jeg det inn!",
  "Välkommen fram!": "Velkommen frem!",
  "Välkommen in! Värm upp lite först så går lyften lättare.": "Velkommen inn! Varm opp litt først, så går løftene lettere.",
  "Välkommen in! ✨": "Velkommen inn! ✨",
  "Välkommen ombord! Vad får det lov att vara?": "Velkommen om bord! Hva skal det være?",
  "Välkommen till BLIXT!": "Velkommen til LYN!",
  "Välkommen till Biblioteket! Ta en bok från hyllan och sätt dig vid ett bord. Varje utläst bok ger en utbildningspoäng.": "Velkommen til Biblioteket! Ta en bok fra hylla og sett deg ved et bord. Hver utlest bok gir ett utdanningspoeng.",
  "Välkommen till Bio Pixel!": "Velkommen til Pixel Kino!",
  "Välkommen till Gamla stan! Huset bakom mig är från 1699 – titta på årtalet i gaveln.": "Velkommen til Gamlebyen! Huset bak meg er fra 1699 – se på årstallet på gavlen.",
  "Välkommen till Klipp & Klo! Har du ett husdjur så gör vi det jättefint här. ✂️": "Velkommen til Klipp & Klo! Har du et husdyr, gjør vi det kjempefint her. ✂️",
  "Välkommen till Klipp & Klo! ✂️ Klicka på trimbordet så fixar vi ditt djur.": "Velkommen til Klipp & Klo! ✂️ Klikk på trimmebordet, så fikser vi dyret ditt.",
  "Välkommen till Kurr! ☕ Fika vid disken – och klappa gärna katterna, de älskar det.": "Velkommen til Kos! ☕ Kjøp kaffe og kake ved disken – og klapp gjerne kattene, de elsker det.",
  "Välkommen till Museet! Titta på föremålen – skyltarna berättar. När du sett tre stycken får du ta quizet hos mig.": "Velkommen til Museet! Se på gjenstandene – skiltene forteller. Når du har sett tre, får du ta quizen hos meg.",
  "Välkommen till Pixel Gym! Hantlarna och boxsäcken ger STYRKA, gruppasset KONDITION och dansgolvet RYTM.": "Velkommen til Pixel Gym! Manualene og boksesekken gir STYRKE, gruppetimen KONDIS og dansegulvet RYTME.",
  "Välkommen till Pixelbanken!": "Velkommen til Pixelbanken!",
  "Välkommen till frisören! Sätt dig i en ledig stol, så fixar vi håret. 💇": "Velkommen til frisøren! Sett deg i en ledig stol, så fikser vi håret. 💇",
  "Välkommen till kassan.": "Velkommen til kassen.",
  "Välkommen till utställningen! Anmäl ditt djur här vid disken – det kostar 100 kr.": "Velkommen til utstillingen! Meld på dyret ditt her ved disken – det koster 100 kr.",
  "Välkommen till {0}! Första föreläsningen är i Aula 1 – sätt dig i en ledig bänk.": "Velkommen til {0}! Første forelesning er i Aula 1 – sett deg på en ledig plass.",
  "Välkommen tillbaka!": "Velkommen tilbake!",
  "Välkommen tillbaka! Allt rullar som det ska? 🔧": "Velkommen tilbake! Ruller alt som det skal? 🔧",
  "Välkommen upp! ⚽ Laget står där borta – klicka på en spelare så provar du matchstället.": "Velkommen opp! ⚽ Laget står der borte – klikk på en spiller, så prøver du kampdrakten.",
  "Välkommen!": "Velkommen!",
  "Välkommen! Ditt sparkonto växer med {0} % i veckan.": "Velkommen! Sparekontoen din vokser med {0} % i uka.",
  "Välkommen! Entrén kostar <b>{0}</b> och gäller hela dagen. Lejonen, elefanterna, girafferna, pingvinerna, klappzoo och ponnyridningen väntar där inne.": "Velkommen! Billetten koster <b>{0}</b> og gjelder hele dagen. Løvene, elefantene, sjiraffene, pingvinene, klappezooen og ponniridningen venter der inne.",
  "Välkommen! Något nytt i dag?": "Velkommen! Noe nytt i dag?",
  "Välkommen! Ska vi prata sparande?": "Velkommen! Skal vi snakke om sparing?",
  "Välkommen! Tentorna skrivs vid tentabordet, lånen här.": "Velkommen! Eksamen tas ved eksamensbordet, utlån her.",
